68	std::shared_ptr<ProofNode> LiaStarProofGenerator::getProofFor(Node fact)
69	{
70	  auto it = d_kind.find(fact);
71	  Assert(it != d_kind.end())
72	      << "LiaStarProofGenerator::getProofFor: unknown fact " << fact;
73	  Info info;
74	  info.d_kind = static_cast<Kind>((*it).second);
75	  auto auxIt = d_aux.find(fact);
76	  Assert(auxIt != d_aux.end());
77	  info.d_aux = (*auxIt).second;
78	  switch (info.d_kind)
79	  {
80	    case Kind::SPLIT: return mkSplitProof(fact, info);
81	    case Kind::NONNEGATIVE: return mkNonnegativeProof(fact, info);
82	    case Kind::CONTAINS_REDUCE: return mkContainsReduceProof(fact, info);
83	    case Kind::GUARD_DEACTIVATE: return mkGuardDeactivateProof(fact, info);
84	  }
85	  Unreachable();
86	}
