88	std::shared_ptr<ProofNode> LiaStarProofGenerator::mkSplitProof(Node lemma,
89	                                                               const Info& info)
90	{
91	  // (or vp (not vp))  via   ProofRule::SPLIT  with arg vp.
92	  CDProof cdp(d_env);
93	  cdp.addStep(lemma, ProofRule::SPLIT, {}, {info.d_aux});
94	  return cdp.getProofFor(lemma);
95	}
