97	std::shared_ptr<ProofNode> LiaStarProofGenerator::mkNonnegativeProof(
98	    Node lemma, const Info& info)
99	{
100	  // The non-negativity lemma is only valid given the originating
101	  // STAR_CONTAINS literal. We emit a TRUST step with the literal as a
102	  // premise, making the proof shape structurally
103	  //   `STAR_CONTAINS(lambda, v) ⊢ (>= v_1 0) ∧ ... ∧ (>= v_n 0)`.
104	  // The TRUST tag remains until a real lia* proof is supplied (e.g. via
105	  // a subsolver call).
106	  CDProof cdp(d_env);
107	  cdp.addTrustedStep(
108	      lemma, TrustId::ARITH_LIA_STAR_NONNEGATIVE, {info.d_aux}, {});
109	  return cdp.getProofFor(lemma);
110	}
