112	std::shared_ptr<ProofNode> LiaStarProofGenerator::mkContainsReduceProof(
113	    Node lemma, const Info& /*info*/)
114	{
115	  // Placeholder: lemma `(= literal star)` is taken on trust under a
116	  // lia*-specific TrustId. To replace with a subsolver proof, prove the
117	  // equivalence `literal <=> star` via a fresh subsolver and transcribe
118	  // its proof onto `getEnv().getProofNodeManager()` here.
119	  CDProof cdp(d_env);
120	  cdp.addTrustedStep(lemma, TrustId::ARITH_LIA_STAR_CONTAINS_REDUCE, {}, {});
121	  return cdp.getProofFor(lemma);
122	}
