124	std::shared_ptr<ProofNode> LiaStarProofGenerator::mkGuardDeactivateProof(
125	    Node lemma, const Info& /*info*/)
126	{
127	  // `lemma` is `(not g)` for a fresh guard `g`; taken on trust since fixing a
128	  // fresh boolean to false is satisfiability-preserving.
129	  CDProof cdp(d_env);
130	  cdp.addTrustedStep(lemma, TrustId::ARITH_LIA_STAR_GUARD_DEACTIVATE, {}, {});
131	  return cdp.getProofFor(lemma);
132	}
